(54016, 1187, 675, '<td valign="top">insane, what the heck is that thing</td>', 'insane, what the heck is that thing', '2002-04-29 18:48:00.000000', NULL, 1),
(54017, 1187, 1350, '<td valign="top">I like the perspective of this pic...and the contrast of the sky and the spiral. Well done!</td>', 'I like the perspective of this pic...and the contrast of the sky and the spiral. Well done!', '2002-04-29 18:53:00.000000', NULL, 1),
(54018, 1187, 1, '<td valign="top">Great shot.  No clue what it is, but it looks great.  I''m wondering if it would look even better perfectly centered?</td>', 'Great shot.  No clue what it is, but it looks great.  I''m wondering if it would look even better perfectly centered?', '2002-04-29 20:25:00.000000', NULL, 1),
(54019, 1187, 1042, '<td valign="top">I like the "web" this forms...nice take.</td>', 'I like the "web" this forms...nice take.', '2002-04-29 20:51:00.000000', NULL, 1),
(54020, 1187, 1344, '<td valign="top">Great subject but lacking something in composition?</td>', 'Great subject but lacking something in composition?', '2002-04-29 22:38:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(54021, 1187, 509, '<td valign="top">Very nice shot, but something about the framing doesn''t seem right, it seems to lean to the left.  Good contrasts as well</td>', 'Very nice shot, but something about the framing doesn''t seem right, it seems to lean to the left.  Good contrasts as well', '2002-04-30 00:34:00.000000', NULL, 1),
(54022, 1187, 1078, '<td valign="top">I find this one very visually interesting and am curious to find out what it is -- my own personal taste would have been to move the center of the thing further to the right (rule of thirds kind of thing) instead of so close to center</td>', 'I find this one very visually interesting and am curious to find out what it is -- my own personal taste would have been to move the center of the thing further to the right (rule of thirds kind of thing) instead of so close to center', '2002-04-30 12:41:00.000000', NULL, 1),
(54023, 1187, 888, '<td valign="top">oo yeah I like it</td>', 'oo yeah I like it', '2002-04-30 14:17:00.000000', NULL, 1),
(54024, 1187, 1041, '<td valign="top">I love the idea!  Would''ve given somewhat higher rating if the angle was differently and the top opening was further off center.  This way, I get the impression it should be centered but isn''t.  Still a good shot.</td>', 'I love the idea!  Would''ve given somewhat higher rating if the angle was differently and the top opening was further off center.  This way, I get the impression it should be centered but isn''t.  Still a good shot.', '2002-04-30 16:34:00.000000', NULL, 1),
(54025, 1187, 782, '<td valign="top">Great exposure.  Good sharp focus.</td>', 'Great exposure.  Good sharp focus.', '2002-04-30 19:12:00.000000', NULL, 1),
(54026, 1187, 1209, '<td valign="top">Whatever this is, I like your image of it! Interesting pic.</td>', 'Whatever this is, I like your image of it! Interesting pic.', '2002-04-30 20:41:00.000000', NULL, 1),
(54027, 1187, 1353, '<td valign="top">Perfect!</td>', 'Perfect!', '2002-04-30 23:06:00.000000', NULL, 1),
(54028, 1187, 543, '<td valign="top">What a great... thing.  I''d like the hole up top just a bit higher and to the right to land on a hotspot - maybe get a cloud in there instead of flat blue sky.  You could have underexposed a little, too, as the detail on the structure is much less important than its shape, and then you might have saved the clouds.</td>', 'What a great... thing.  I''d like the hole up top just a bit higher and to the right to land on a hotspot - maybe get a cloud in there instead of flat blue sky.  You could have underexposed a little, too, as the detail on the structure is much less important than its shape, and then you might have saved the clouds.', '2002-05-01 09:54:00.000000', NULL, 1),
(54029, 1187, 714, '<td valign="top">Cool, I like it.</td>', 'Cool, I like it.', '2002-05-01 12:49:00.000000', NULL, 1),
(54030, 1187, 933, '<td valign="top">Not too sure what this is, but it makes for an interesting design in a photo.  nice job.</td>', 'Not too sure what this is, but it makes for an interesting design in a photo.  nice job.', '2002-05-02 14:55:00.000000', NULL, 1),
(54031, 1187, 748, '<td valign="top">Very interesting shot.  I like it.</td>', 'Very interesting shot.  I like it.', '2002-05-02 18:58:00.000000', NULL, 1),
(54032, 1187, 1202, '<td valign="top">Truely a ground up shot, but it leaves me empty.   Most of us old folks like a little story line in the picture....something to ponder in the future.</td>', 'Truely a ground up shot, but it leaves me empty.   Most of us old folks like a little story line in the picture....something to ponder in the future.', '2002-05-04 08:37:00.000000', NULL, 1),
(54033, 1187, 1070, '<td valign="top">love it</td>', 'love it', '2002-05-05 12:39:00.000000', NULL, 1),
(54034, 1187, 2, '<td valign="top">Great feeling of depth in this photo.  I really feel constrained in the object.</td>', 'Great feeling of depth in this photo.  I really feel constrained in the object.', '2002-05-05 13:14:00.000000', NULL, 1),
(54035, 1187, 842, '<td valign="top">This is a circular sculpture located outside of the &amp;lt;a href="//www.uwajimaya.com/retailstores_seattle.html"&amp;gt;Uwajimaya Asian Marke&amp;lt;/a&amp;gt;t in Seattle. The photo was taken from the bottom which is located in the parking garage looking up.</td>', 'This is a circular sculpture located outside of the &lt;a href="//www.uwajimaya.com/retailstores_seattle.html"&gt;Uwajimaya Asian Marke&lt;/a&gt;t in Seattle. The photo was taken from the bottom which is located in the parking garage looking up.', '2002-05-06 01:23:00.000000', NULL, 0),
(54036, 1189, 656, '<td valign="top">normally it''s good for these if you can get the horizon to be flat, rather than tilted.  Maybe have been more interesting about 30 minutes later when the sun had gone down more ?</td>', 'normally it''s good for these if you can get the horizon to be flat, rather than tilted.  Maybe have been more interesting about 30 minutes later when the sun had gone down more ?', '2002-04-29 09:34:00.000000', NULL, 1),
(54037, 1189, 259, '<td valign="top">nice sunset picture, but not really from the ground up as much as other photos in the contest.</td>', 'nice sunset picture, but not really from the ground up as much as other photos in the contest.', '2002-04-29 10:45:00.000000', NULL, 1),
(54038, 1189, 189, '<td valign="top">too dark.</td>', 'too dark.', '2002-04-29 11:11:00.000000', NULL, 1),
(54039, 1189, 772, '<td valign="top">i really do like nice sunset photos and there are some good ones in almost every challenge on this site...  in this photo, i''m trying to determine where "from the ground up" is displayed.  i see that your camera is close to the ground, but you are shooting just about level with the horizon.   I could be missing the point here but i don''t see it.</td>', 'i really do like nice sunset photos and there are some good ones in almost every challenge on this site...  in this photo, i''m trying to determine where "from the ground up" is displayed.  i see that your camera is close to the ground, but you are shooting just about level with the horizon.   I could be missing the point here but i don''t see it.', '2002-04-29 13:27:00.000000', NULL, 1),
(54040, 1189, 1379, '<td valign="top">Glorious</td>', 'Glorious', '2002-04-29 15:20:00.000000', NULL, 1),
(54041, 1189, 675, '<td valign="top">interesting interpretation of the challenge</td>', 'interesting interpretation of the challenge', '2002-04-29 18:33:00.000000', NULL, 1),
(54042, 1189, 301, '<td valign="top">lovely sunset.  Two things: 1) the horizon seems crooked to me<br/>2) the three blades of grass in the foreground are really distracting. Probably better to move the camera forwards slightly and take them out.  The other grass silhouettes are ok</td>', 'lovely sunset.  Two things: 1) the horizon seems crooked to me2) the three blades of grass in the foreground are really distracting. Probably better to move the camera forwards slightly and take them out.  The other grass silhouettes are ok', '2002-04-30 07:30:00.000000', NULL, 1),
(54043, 1189, 888, '<td valign="top">very good</td>', 'very good', '2002-04-30 14:32:00.000000', NULL, 1),
(54044, 1189, 280, '<td valign="top">Nice shot, but I think a higher angle would suit the challenge better.</td>', 'Nice shot, but I think a higher angle would suit the challenge better.', '2002-04-30 16:23:00.000000', NULL, 1),
(54045, 1189, 1041, '<td valign="top">Nice angle, and unusual approach to sunset.  Would the sunflare be less dominating the picture if the person stood more in front of it?  Also, the out of focus grass in the foreground is slightly distracting.</td>', 'Nice angle, and unusual approach to sunset.  Would the sunflare be less dominating the picture if the person stood more in front of it?  Also, the out of focus grass in the foreground is slightly distracting.', '2002-04-30 17:05:00.000000', NULL, 1),
(54046, 1189, 244, '<td valign="top">Nice picture, love the placement of the individual slightly blocking the sun, would have cropped out the lamp post though.</td>', 'Nice picture, love the placement of the individual slightly blocking the sun, would have cropped out the lamp post though.', '2002-05-02 21:14:00.000000', NULL, 1),
(54047, 1189, 330, '<td valign="top">Nice picture. I like the flare here.</td>', 'Nice picture. I like the flare here.', '2002-05-03 07:03:00.000000', NULL, 1),
(54048, 1189, 885, '<td valign="top">The lamp-post sort of draws you out of the nature scene a bit.</td>', 'The lamp-post sort of draws you out of the nature scene a bit.', '2002-05-03 15:11:00.000000', NULL, 1),
(54049, 1189, 387, '<td valign="top">Some slightly different cropping would have made this an even better shot. But dont get discouraged, its nice.</td>', 'Some slightly different cropping would have made this an even better shot. But dont get discouraged, its nice.', '2002-05-03 16:12:00.000000', NULL, 1),
(54050, 1189, 828, '<td valign="top">Really nice.  If only the sun were just a little more shielded by the figure.  I like it, though.</td>', 'Really nice.  If only the sun were just a little more shielded by the figure.  I like it, though.', '2002-05-03 23:23:00.000000', NULL, 1),
(54051, 1189, 1070, '<td valign="top">I love to shoot into a light source creating wonderful effects with silhouettes but would have liked the foreground to have been the subject of focus.<br/>Your well thought out angle creates a lovely effect on the silhouetted figure.<br/></td>', 'I love to shoot into a light source creating wonderful effects with silhouettes but would have liked the foreground to have been the subject of focus.Your well thought out angle creates a lovely effect on the silhouetted figure.', '2002-05-05 11:06:00.000000', NULL, 1),
(54052, 1189, 1, '<td valign="top">The scattered blades of grass seem distracting from the silhouette/sun.</td>', 'The scattered blades of grass seem distracting from the silhouette/sun.', '2002-05-05 23:28:00.000000', NULL, 1),
(54057, 1194, 301, '<td valign="top">shadow from the flash is kinda cool.  The colouring doesn''t do anything for me, and the doorway in the background is very distracting - I keep expecting to see something in there</td>', 'shadow from the flash is kinda cool.  The colouring doesn''t do anything for me, and the doorway in the background is very distracting - I keep expecting to see something in there', '2002-04-29 07:35:00.000000', NULL, 1),
(54058, 1194, 1024, '<td valign="top">Nice use of black and white.</td>', 'Nice use of black and white.', '2002-04-29 08:53:00.000000', NULL, 1),
(54059, 1194, 885, '<td valign="top">His paws and the tip of his nose are cut off!  Is this a black dog?  It''s a great pose...the background and shadow are a bit distracting and it seems maybe something could be done with the lighting to show off the texture of his fur a bit more, though I''ve not had much experience with it, so I couldn''t really tell you what.</td>', 'His paws and the tip of his nose are cut off!  Is this a black dog?  It''s a great pose...the background and shadow are a bit distracting and it seems maybe something could be done with the lighting to show off the texture of his fur a bit more, though I''ve not had much experience with it, so I couldn''t really tell you what.', '2002-04-29 09:17:00.000000', NULL, 1),
(54060, 1194, 656, '<td valign="top">cool fur textures</td>', 'cool fur textures', '2002-04-29 10:10:00.000000', NULL, 1),
(54061, 1194, 772, '<td valign="top">Black dogs are hard to photograph, huh?  i would rather see the nose not cropped out of this shot....  the background is a little busy as well... Nice shot though...</td>', 'Black dogs are hard to photograph, huh?  i would rather see the nose not cropped out of this shot....  the background is a little busy as well... Nice shot though...', '2002-04-29 13:47:00.000000', NULL, 1),
(54062, 1194, 1175, '<td valign="top">Cute dog.  Your flash is a bit too loud.  You need a little more to make thi picture more interesting.</td>', 'Cute dog.  Your flash is a bit too loud.  You need a little more to make thi picture more interesting.', '2002-04-29 14:09:00.000000', NULL, 1),
(54063, 1194, 1336, '<td valign="top">the background is too busy with the couch, chair, and doorway.</td>', 'the background is too busy with the couch, chair, and doorway.', '2002-04-29 14:49:00.000000', NULL, 1),
(54064, 1194, 813, '<td valign="top">Nice. Your compostion makes the dog look like it''s as tall as the ceiling. Would love to see a little better contrast, but excellent shot.</td>', 'Nice. Your compostion makes the dog look like it''s as tall as the ceiling. Would love to see a little better contrast, but excellent shot.', '2002-04-29 14:49:00.000000', NULL, 1),
(54065, 1194, 327, '<td valign="top">Cool shot and done well. Poor crop but I''ll bet size was the reason.<br/>Nice work.</td>', 'Cool shot and done well. Poor crop but I''ll bet size was the reason.Nice work.', '2002-04-29 14:51:00.000000', NULL, 1),
(54066, 1194, 675, '<td valign="top">that''s funny</td>', 'that''s funny', '2002-04-29 18:23:00.000000', NULL, 1),
(54067, 1194, 107, '<td valign="top">I would have liked to see his entire  nose in the picture.. and I''m not sure the black and white add anything to this image.  A good idea though.</td>', 'I would have liked to see his entire  nose in the picture.. and I''m not sure the black and white add anything to this image.  A good idea though.', '2002-04-30 02:55:00.000000', NULL, 1),
(54068, 1194, 1078, '<td valign="top">black and white was a great choice for this one -- really shows the glossy coat -- I think it would have been better off in a less distracting space (no sofa, rocking chair, doorway, etc) and if the tip of the dog''s nose hadn''t been cut from the image</td>', 'black and white was a great choice for this one -- really shows the glossy coat -- I think it would have been better off in a less distracting space (no sofa, rocking chair, doorway, etc) and if the tip of the dog''s nose hadn''t been cut from the image', '2002-04-30 12:35:00.000000', NULL, 1),
(54069, 1194, 888, '<td valign="top">mans best friend. shame about the background, it really detracts from the otherwise great figure</td>', 'mans best friend. shame about the background, it really detracts from the otherwise great figure', '2002-04-30 16:35:00.000000', NULL, 1),
(54070, 1194, 1041, '<td valign="top">Nice angle, like the black and white.  Head seems a tad soft, nose is cut off, and some of the background is distracting.</td>', 'Nice angle, like the black and white.  Head seems a tad soft, nose is cut off, and some of the background is distracting.', '2002-04-30 17:04:00.000000', NULL, 1),
(54071, 1194, 543, '<td valign="top">A guitarist''s doggie?  Think I''m starting to recognize your style.  The hot flash makes for interesting tone, but not really pleasing.  That''s not a good or bad thing, I guess, but can''t say the same for the shadow and crop.</td>', 'A guitarist''s doggie?  Think I''m starting to recognize your style.  The hot flash makes for interesting tone, but not really pleasing.  That''s not a good or bad thing, I guess, but can''t say the same for the shadow and crop.', '2002-05-01 11:29:00.000000', NULL, 1),
(54072, 1194, 901, '<td valign="top">i like how it makes the doggie look big. ha ha</td>', 'i like how it makes the doggie look big. ha ha', '2002-05-02 01:50:00.000000', NULL, 1),
(54073, 1194, 933, '<td valign="top">His wee little nose is cropped off.  I think framing the whole dog inside the image would have helped.</td>', 'His wee little nose is cropped off.  I think framing the whole dog inside the image would have helped.', '2002-05-03 15:21:00.000000', NULL, 1),
(54074, 1194, 1202, '<td valign="top">Healthy coat.   I fell a little more eye would help give your shot a story line.  Tough challenge though.</td>', 'Healthy coat.   I fell a little more eye would help give your shot a story line.  Tough challenge though.', '2002-05-04 08:12:00.000000', NULL, 1),
(54075, 1194, 1, '<td valign="top">The background doesn''t well for this shot.  An outdoor setting for the dog would be lots better.</td>', 'The background doesn''t well for this shot.  An outdoor setting for the dog would be lots better.', '2002-05-04 11:03:00.000000', NULL, 1),
(54076, 1195, 301, '<td valign="top">Although the camera was probably on the ground, I don''t really get the sense of looking up</td>', 'Although the camera was probably on the ground, I don''t really get the sense of looking up', '2002-04-29 06:18:00.000000', NULL, 1),
(54077, 1195, 1233, '<td valign="top">Nice interpretation of the subject.</td>', 'Nice interpretation of the subject.', '2002-04-29 06:38:00.000000', NULL, 1),
(54078, 1195, 656, '<td valign="top">Could have done with being closer, and turning the camera to shoot it vertically.</td>', 'Could have done with being closer, and turning the camera to shoot it vertically.', '2002-04-29 09:32:00.000000', NULL, 1),
(54079, 1195, 862, '<td valign="top">I like your interpretation of the challenge, but this shot needs better focus.</td>', 'I like your interpretation of the challenge, but this shot needs better focus.', '2002-04-29 10:02:00.000000', NULL, 1),
(54080, 1195, 675, '<td valign="top">doesn''t really get at the point of the challenge</td>', 'doesn''t really get at the point of the challenge', '2002-04-29 10:25:00.000000', NULL, 1),
(54081, 1195, 1037, '<td valign="top">Hmm... I think it could do with more contrast... but even then the subject matter isn''t very interesting or captured in a unique way :/</td>', 'Hmm... I think it could do with more contrast... but even then the subject matter isn''t very interesting or captured in a unique way :/', '2002-04-29 10:49:00.000000', NULL, 1),
(54082, 1195, 259, '<td valign="top">looks to much like a snap shot.  not very artistic.</td>', 'looks to much like a snap shot.  not very artistic.', '2002-04-29 11:51:00.000000', NULL, 1),
(54083, 1195, 1175, '<td valign="top">"from the perspective of the ground up."  I don''t agree with your translation.  Putting that aside, your picture looks to much like a snapshot.  THe lighting is a bit dark, I feel like I''m looking through tinted glass.</td>', '"from the perspective of the ground up."  I don''t agree with your translation.  Putting that aside, your picture looks to much like a snapshot.  THe lighting is a bit dark, I feel like I''m looking through tinted glass.', '2002-04-29 12:37:00.000000', NULL, 1),
(54084, 1195, 885, '<td valign="top">Feels a bit flat and dark..and I don''t really feel the perspective.  Maybe you could have moved in on the crane and pointed the camera up more.</td>', 'Feels a bit flat and dark..and I don''t really feel the perspective.  Maybe you could have moved in on the crane and pointed the camera up more.', '2002-04-29 12:43:00.000000', NULL, 1),
(54085, 1195, 1336, '<td valign="top">it would be nice if the shot was a little tighter</td>', 'it would be nice if the shot was a little tighter', '2002-04-29 14:21:00.000000', NULL, 1),
(54086, 1195, 772, '<td valign="top">Good challenge concept here... The picture seems just a tad dim..  the contrast is a little low...</td>', 'Good challenge concept here... The picture seems just a tad dim..  the contrast is a little low...', '2002-04-29 14:32:00.000000', NULL, 1),
(54087, 1195, 1379, '<td valign="top">Every little boy''s dream come true...</td>', 'Every little boy''s dream come true...', '2002-04-29 15:10:00.000000', NULL, 1),
(54088, 1195, 962, '<td valign="top">No relation to the topic.......</td>', 'No relation to the topic.......', '2002-04-29 16:46:00.000000', NULL, 1),
(54089, 1195, 1041, '<td valign="top">A different interpretation of "from the ground up".  Not the one I think was intended by the challenge.  Otherwise an ok photo, but not one that holds my interest very long.</td>', 'A different interpretation of "from the ground up".  Not the one I think was intended by the challenge.  Otherwise an ok photo, but not one that holds my interest very long.', '2002-04-30 11:39:00.000000', NULL, 1),
(54090, 1195, 1078, '<td valign="top">K, I get the challenge aspect -- considered shooting something similar -- the contrast on this seems flat though -- I also find the composition to be kind of bland -- would it have been possible to get any closer to the construction site?</td>', 'K, I get the challenge aspect -- considered shooting something similar -- the contrast on this seems flat though -- I also find the composition to be kind of bland -- would it have been possible to get any closer to the construction site?', '2002-04-30 12:49:00.000000', NULL, 1),
(54091, 1195, 888, '<td valign="top">It would have been better if you''d been closer up with the camera vertically capturing just the crane and sky</td>', 'It would have been better if you''d been closer up with the camera vertically capturing just the crane and sky', '2002-04-30 14:07:00.000000', NULL, 1),
(54092, 1195, 387, '<td valign="top">I didn''t score your shot based on whether your camera was pointed upwards. However, I felt the shot was too ''bland''. The composition wasn''t bad but the shot had a flat feel. Please don''t take offense.</td>', 'I didn''t score your shot based on whether your camera was pointed upwards. However, I felt the shot was too ''bland''. The composition wasn''t bad but the shot had a flat feel. Please don''t take offense.', '2002-04-30 19:46:00.000000', NULL, 1),
(54093, 1195, 280, '<td valign="top">A good take on ''ground up'' but this construction hasnt got very far yet : )</td>', 'A good take on ''ground up'' but this construction hasnt got very far yet : )', '2002-05-01 17:19:00.000000', NULL, 1),
(54094, 1195, 811, '<td valign="top">What would have been really cool is to take a picture looking up the crane, but obviously you can''t just go running onto a construction site.  Maybed taken from different angle or making the crane the focal point instead of just part of the picture.  Black and white might have been neat.</td>', 'What would have been really cool is to take a picture looking up the crane, but obviously you can''t just go running onto a construction site.  Maybed taken from different angle or making the crane the focal point instead of just part of the picture.  Black and white might have been neat.', '2002-05-02 09:52:00.000000', NULL, 1),
(54095, 1195, 933, '<td valign="top">The subject of this image just does not do a lot for me.</td>', 'The subject of this image just does not do a lot for me.', '2002-05-02 15:13:00.000000', NULL, 1),
(54096, 1195, 640, '<td valign="top">A tad dark--or is it my screen?</td>', 'A tad dark--or is it my screen?', '2002-05-03 01:29:00.000000', NULL, 1),
(54097, 1195, 330, '<td valign="top">I like the more literal interpretations of the challenge.</td>', 'I like the more literal interpretations of the challenge.', '2002-05-03 07:10:00.000000', NULL, 1),
(54098, 1195, 436, '<td valign="top">lighting is flat.  I wish I could fix that on my own work!</td>', 'lighting is flat.  I wish I could fix that on my own work!', '2002-05-03 08:17:00.000000', NULL, 1),
(54099, 1195, 1457, '<td valign="top">boring</td>', 'boring', '2002-05-04 23:11:00.000000', NULL, 1),
(54100, 1195, 2, '<td valign="top">I''m guessing you''re taking the ''ground up'' interpretation of ''building'' ... but even if so, the picture seems really boring and washed out.</td>', 'I''m guessing you''re taking the ''ground up'' interpretation of ''building'' ... but even if so, the picture seems really boring and washed out.', '2002-05-05 13:15:00.000000', NULL, 1),
(54101, 1195, 1469, '<td valign="top">The brightness is lacking, but great idea!</td>', 'The brightness is lacking, but great idea!', '2002-05-05 18:10:00.000000', NULL, 1),
(54102, 1195, 1, '<td valign="top">Bland subject matter.  Ground up isn''t really represented well.</td>', 'Bland subject matter.  Ground up isn''t really represented well.', '2002-05-05 23:04:00.000000', NULL, 1),
(54103, 1197, 801, '<td valign="top">well done!!</td>', 'well done!!', '2002-04-29 04:13:00.000000', NULL, 1),
(54104, 1197, 301, '<td valign="top">I like the black &amp; white but I''d prefer to see the face</td>', 'I like the black & white but I''d prefer to see the face', '2002-04-29 07:27:00.000000', NULL, 1),
(54105, 1197, 1024, '<td valign="top">Black and white really works in this photo.  Much better than if you had done it in color.</td>', 'Black and white really works in this photo.  Much better than if you had done it in color.', '2002-04-29 08:18:00.000000', NULL, 1),
(54106, 1197, 656, '<td valign="top">Nicely framed, with the diagonals and horizontal line.  Good use of B&amp;W too.</td>', 'Nicely framed, with the diagonals and horizontal line.  Good use of B&W too.', '2002-04-29 09:29:00.000000', NULL, 1),
(54107, 1197, 675, '<td valign="top">my eyes keep getting drawn to the arm covering the woman''s face, which is not a good thing, considering the rest of this picture is great</td>', 'my eyes keep getting drawn to the arm covering the woman''s face, which is not a good thing, considering the rest of this picture is great', '2002-04-29 10:08:00.000000', NULL, 1),
