(54336, 1209, 1371, '<td valign="top">Gorgeous.</td>', 'Gorgeous.', '2002-04-29 12:36:00.000000', NULL, 1),
(54337, 1209, 544, '<td valign="top">You did a nice job on getting the color of this photo right; it matches the feel of the image quite well. You also did a good job of getting the subjects well-lit, and filling the entire image with texture - i.e. the hair on the legs, the paper from the pages of one book, and the bumps on the bottom of the other book. Even the wall and door have been captured well, despite their not being the focus of the picture. Great.</td>', 'You did a nice job on getting the color of this photo right; it matches the feel of the image quite well. You also did a good job of getting the subjects well-lit, and filling the entire image with texture - i.e. the hair on the legs, the paper from the pages of one book, and the bumps on the bottom of the other book. Even the wall and door have been captured well, despite their not being the focus of the picture. Great.', '2002-04-29 14:31:00.000000', NULL, 1),
(54338, 1209, 1379, '<td valign="top">Great sepia coloring!  Makes for a very rustic shot.</td>', 'Great sepia coloring!  Makes for a very rustic shot.', '2002-04-29 14:47:00.000000', NULL, 1),
