(54613, 1234, 554, '<td valign="top">one of the best!</td>', 'one of the best!', '2002-04-30 20:59:00.000000', NULL, 1),
(54614, 1234, 885, '<td valign="top">I like the color...kind of monochromatic.  I might experiment with cropping to see if it was improved by leaving out the corner of the building.</td>', 'I like the color...kind of monochromatic.  I might experiment with cropping to see if it was improved by leaving out the corner of the building.', '2002-05-01 10:20:00.000000', NULL, 1),
(54615, 1234, 543, '<td valign="top">Another one that would work really well in B/W, or even better with the man selectively colored (all that nice blue) and the rest B/W.  Noisy and jaggy as all get out, but that can usually be fixed.</td>', 'Another one that would work really well in B/W, or even better with the man selectively colored (all that nice blue) and the rest B/W.  Noisy and jaggy as all get out, but that can usually be fixed.', '2002-05-01 10:51:00.000000', NULL, 1),
(54616, 1234, 310, '<td valign="top">Good idea and execution.</td>', 'Good idea and execution.', '2002-05-01 14:40:00.000000', NULL, 1),
(54617, 1234, 1066, '<td valign="top">Nice shot.  One of those photos that you cannot vote on fairly in the thumbnail.  the glass is interesting with its hangers and his reflection is good too.  Makes me wish I had building where they needed window washers.  good shot</td>', 'Nice shot.  One of those photos that you cannot vote on fairly in the thumbnail.  the glass is interesting with its hangers and his reflection is good too.  Makes me wish I had building where they needed window washers.  good shot', '2002-05-01 17:28:00.000000', NULL, 1),
(54618, 1234, 739, '<td valign="top">Great subject.  Would have liked to see a more vertical perspective.</td>', 'Great subject.  Would have liked to see a more vertical perspective.', '2002-05-01 21:19:00.000000', NULL, 1),
(54619, 1234, 637, '<td valign="top">This would''ve been more powerful if caught from further below.</td>', 'This would''ve been more powerful if caught from further below.', '2002-05-03 19:56:00.000000', NULL, 1),
(54620, 1234, 1202, '<td valign="top">Could you just edge your way out there a little farther and get more of an upshot angle.   There thats better.....ooops.   All kidding aside, nice shot, especially if it were a little clearer.</td>', 'Could you just edge your way out there a little farther and get more of an upshot angle.   There thats better.....ooops.   All kidding aside, nice shot, especially if it were a little clearer.', '2002-05-04 08:41:00.000000', NULL, 1),
(54621, 1234, 1, '<td valign="top">Cool shot, nice angle.  What kind of zoom was used for this?  Or was the man not too high up?</td>', 'Cool shot, nice angle.  What kind of zoom was used for this?  Or was the man not too high up?', '2002-05-05 23:20:00.000000', NULL, 1),
(54622, 1234, 797, '<td valign="top">nice coloring of the shot. perspective is nice, though i wonder if it could have been more leading.</td>', 'nice coloring of the shot. perspective is nice, though i wonder if it could have been more leading.', '2002-05-06 00:56:00.000000', NULL, 1),
(54623, 1235, 1024, '<td valign="top">Very nice.</td>', 'Very nice.', '2002-04-29 08:40:00.000000', NULL, 1),
