(54625, 1235, 675, '<td valign="top">what a cliche, but on the other hand, one of my favorites so far, really good execution on something that might have been boring, i reallly like this one</td>', 'what a cliche, but on the other hand, one of my favorites so far, really good execution on something that might have been boring, i reallly like this one', '2002-04-29 10:12:00.000000', NULL, 1),
