INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(54627, 1235, 1042, '<td valign="top">I love the title and I like that it really looks like your viewing it from a squirrel''s point of view.</td>', 'I love the title and I like that it really looks like your viewing it from a squirrel''s point of view.', '2002-04-29 11:54:00.000000', NULL, 1),
(54628, 1235, 259, '<td valign="top">great photo and title.</td>', 'great photo and title.', '2002-04-29 12:00:00.000000', NULL, 1),
(54629, 1235, 885, '<td valign="top">Nice composition, colors.  Contrasty scene, the top is a bit overexposed, polarizer might have darkened up the sky.</td>', 'Nice composition, colors.  Contrasty scene, the top is a bit overexposed, polarizer might have darkened up the sky.', '2002-04-29 12:21:00.000000', NULL, 1),
(54630, 1235, 724, '<td valign="top">Nice colors here. Am I missing the squirrel?</td>', 'Nice colors here. Am I missing the squirrel?', '2002-04-29 21:38:00.000000', NULL, 1),
(54631, 1235, 813, '<td valign="top">Good composition and focus. Appropriate title too. It would have been great if a squirrel were seen scampering up the tree in a blur.</td>', 'Good composition and focus. Appropriate title too. It would have been great if a squirrel were seen scampering up the tree in a blur.', '2002-04-30 09:54:00.000000', NULL, 1),
(54632, 1235, 714, '<td valign="top">Nice photo.</td>', 'Nice photo.', '2002-04-30 10:02:00.000000', NULL, 1),
(54633, 1235, 640, '<td valign="top">beautiful tree</td>', 'beautiful tree', '2002-04-30 11:09:00.000000', NULL, 1),
(54634, 1235, 554, '<td valign="top">10</td>', '10', '2002-04-30 14:19:00.000000', NULL, 1),
(54635, 1235, 1041, '<td valign="top">Nice clear picture, good colors.  Funny title, a squirrel would''ve given a great focal point to the picture.</td>', 'Nice clear picture, good colors.  Funny title, a squirrel would''ve given a great focal point to the picture.', '2002-04-30 14:23:00.000000', NULL, 1),
(54636, 1235, 1209, '<td valign="top">Fascinating view, nicely done.</td>', 'Fascinating view, nicely done.', '2002-04-30 16:06:00.000000', NULL, 1),
(54637, 1235, 1135, '<td valign="top">Clever Title. Looks like you really could run right up the tree.</td>', 'Clever Title. Looks like you really could run right up the tree.', '2002-04-30 16:49:00.000000', NULL, 1),
