(54880, 1254, 280, '<td valign="top">good compsition, good colours, but this shot just doesnt grab me.</td>', 'good compsition, good colours, but this shot just doesnt grab me.', '2002-04-30 16:43:00.000000', NULL, 1),
(54881, 1254, 1135, '<td valign="top">Excellent Color and Focus! Very nice shot.</td>', 'Excellent Color and Focus! Very nice shot.', '2002-04-30 16:47:00.000000', NULL, 1),
(54882, 1254, 543, '<td valign="top">It''s all about light, and you got that just right.  Good use of negative space and color.  I''d like to see a little more of the bottom - "where the rubber meets the road" so to speak, but that''s your choice.  Well done!</td>', 'It''s all about light, and you got that just right.  Good use of negative space and color.  I''d like to see a little more of the bottom - "where the rubber meets the road" so to speak, but that''s your choice.  Well done!', '2002-05-01 04:18:00.000000', NULL, 1),
(54883, 1254, 885, '<td valign="top">Quite nice.  I like the off-set framing and the red jumpsuit.  Though it appears that the rider isn''t actually riding, since his feet aren''t on the pedals, the fact that you left out the bottom of the wheel makes it seem as though the wheel could be off the ground.  Well done.</td>', 'Quite nice.  I like the off-set framing and the red jumpsuit.  Though it appears that the rider isn''t actually riding, since his feet aren''t on the pedals, the fact that you left out the bottom of the wheel makes it seem as though the wheel could be off the ground.  Well done.', '2002-05-01 09:54:00.000000', NULL, 1),
(54884, 1254, 1041, '<td valign="top">Argh!  Dangerous!  Nice clean shot.  Like the red of the clothes against the blue of the sky.  Not a big fan of cut-off head though.  Definitely completed the challenge!</td>', 'Argh!  Dangerous!  Nice clean shot.  Like the red of the clothes against the blue of the sky.  Not a big fan of cut-off head though.  Definitely completed the challenge!', '2002-05-01 10:48:00.000000', NULL, 1),
(54885, 1254, 156, '<td valign="top">showing more of the bottom of the tire would be more in keeping with the perspective of the ground up, but i still like it!</td>', 'showing more of the bottom of the tire would be more in keeping with the perspective of the ground up, but i still like it!', '2002-05-01 13:24:00.000000', NULL, 1),
(54886, 1254, 1078, '<td valign="top">nice use of color and lighting - would personally like to see the picture a tiny bit brighter - am also a little bothered by the rider''s head having been cut off, but I think I would have been even more distracted from the over all image if it had been included</td>', 'nice use of color and lighting - would personally like to see the picture a tiny bit brighter - am also a little bothered by the rider''s head having been cut off, but I think I would have been even more distracted from the over all image if it had been included', '2002-05-01 16:48:00.000000', NULL, 1),
