(55143, 1269, 117, '<td valign="top">I hope that isn''t digital editing, I scored it high, would have gave it a 10 if I knew for sure. great shot</td>', 'I hope that isn''t digital editing, I scored it high, would have gave it a 10 if I knew for sure. great shot', '2002-04-29 16:57:00.000000', NULL, 1),
(55144, 1269, 1005, '<td valign="top">Very cool! Good timing!</td>', 'Very cool! Good timing!', '2002-04-29 17:53:00.000000', NULL, 1),
(55145, 1269, 675, '<td valign="top">i don''t know how this is from the ground up, but i like geysers</td>', 'i don''t know how this is from the ground up, but i like geysers', '2002-04-29 18:33:00.000000', NULL, 1),
(55146, 1269, 1350, '<td valign="top">I really like this photo. Great contrast and color. Well done!</td>', 'I really like this photo. Great contrast and color. Well done!', '2002-04-29 19:13:00.000000', NULL, 1),
(55147, 1269, 772, '<td valign="top">This is a beautiful shot...  I can''t say much for improvements other than having the geyser fully in the frame and not clipped at the top... excellent work!</td>', 'This is a beautiful shot...  I can''t say much for improvements other than having the geyser fully in the frame and not clipped at the top... excellent work!', '2002-04-30 05:47:00.000000', NULL, 1),
(55148, 1269, 813, '<td valign="top">Very nice. I like the fact the theme is captured without pointing the camera up. Bravo for thinking differently. Good composition, focus, and exposure too!</td>', 'Very nice. I like the fact the theme is captured without pointing the camera up. Bravo for thinking differently. Good composition, focus, and exposure too!', '2002-04-30 09:56:00.000000', NULL, 1),
(55149, 1269, 459, '<td valign="top">Geyser at dawn?  What a great subject for "from the ground up"!  Nice photo</td>', 'Geyser at dawn?  What a great subject for "from the ground up"!  Nice photo', '2002-04-30 10:18:00.000000', NULL, 1),
(55150, 1269, 888, '<td valign="top">wow is that a geyser?<br/>Thats a great pic<br/>the sun set makes it even better</td>', 'wow is that a geyser?Thats a great picthe sun set makes it even better', '2002-04-30 17:05:00.000000', NULL, 1),
(55151, 1269, 1211, '<td valign="top">Nice shot.  Rich colors, which is especially hard when it is this dark out.  I especially like the way the clouds contrast the blue sky so nicely.</td>', 'Nice shot.  Rich colors, which is especially hard when it is this dark out.  I especially like the way the clouds contrast the blue sky so nicely.', '2002-04-30 17:47:00.000000', NULL, 1),
(55152, 1269, 782, '<td valign="top">This picture would have been really spectacular with a fill flash</td>', 'This picture would have been really spectacular with a fill flash', '2002-04-30 19:23:00.000000', NULL, 1),
(55153, 1269, 387, '<td valign="top">I opened my mind and revoted your shot. It''s a beautiful shot.</td>', 'I opened my mind and revoted your shot. It''s a beautiful shot.', '2002-04-30 19:56:00.000000', NULL, 1),
(55154, 1269, 543, '<td valign="top">You getting creamed for insufficient lens elevation, too?  It''s a really nice catch.  Wish I could see your settings.</td>', 'You getting creamed for insufficient lens elevation, too?  It''s a really nice catch.  Wish I could see your settings.', '2002-05-01 10:19:00.000000', NULL, 1),
