(55156, 1269, 301, '<td valign="top">wow - got no idea what it is.  Would prefer it centred and the foreground brighter</td>', 'wow - got no idea what it is.  Would prefer it centred and the foreground brighter', '2002-05-01 12:00:00.000000', NULL, 1),
(55157, 1269, 748, '<td valign="top">Neat interpretation.  I like the shot.</td>', 'Neat interpretation.  I like the shot.', '2002-05-01 15:43:00.000000', NULL, 1),
