(55169, 1269, 1, '<td valign="top">Great shot!  The timing, not only to catch the uhh...whatever that is, but the time of day as well makes the image look great.</td>', 'Great shot!  The timing, not only to catch the uhh...whatever that is, but the time of day as well makes the image look great.', '2002-05-05 22:55:00.000000', NULL, 1),
(55170, 1269, 2, '<td valign="top">Really cool colors in this photo.  Can''t wait to see where it was taken.</td>', 'Really cool colors in this photo.  Can''t wait to see where it was taken.', '2002-05-05 23:36:00.000000', NULL, 1),
(55171, 1269, 4492, '<td valign="top">How did you do it? I agree with bobgaither, you definitely should have received a better score.</td>', 'How did you do it? I agree with bobgaither, you definitely should have received a better score.', '2002-10-10 04:03:00.000000', NULL, 0),
(55172, 1270, 205, '<td valign="top">I''ve seen this so many times but your perspective kicks the crap out of the other compositions.</td>', 'I''ve seen this so many times but your perspective kicks the crap out of the other compositions.', '2002-04-29 01:39:00.000000', NULL, 1),
(55173, 1270, 446, '<td valign="top">Nice shot.  I like the exposure.  I rated this very high.  I think you are in contention for a ribbon.</td>', 'Nice shot.  I like the exposure.  I rated this very high.  I think you are in contention for a ribbon.', '2002-04-29 02:06:00.000000', NULL, 1),
