(55182, 1270, 1024, '<td valign="top">This is a very strong (no pun intended) photograph.</td>', 'This is a very strong (no pun intended) photograph.', '2002-04-29 13:04:00.000000', NULL, 1),
(55183, 1270, 1336, '<td valign="top">i really like the subject, especially with the building in the background, but i wonder if this could have been taken at a different time during the day to make the lighting more complimentary</td>', 'i really like the subject, especially with the building in the background, but i wonder if this could have been taken at a different time during the day to make the lighting more complimentary', '2002-04-29 14:34:00.000000', NULL, 1),
(55184, 1270, 327, '<td valign="top">Clever!</td>', 'Clever!', '2002-04-29 14:52:00.000000', NULL, 1),
(55185, 1270, 1379, '<td valign="top">AWESOME framing!  This photo is intense!</td>', 'AWESOME framing!  This photo is intense!', '2002-04-29 14:59:00.000000', NULL, 1),
(55186, 1270, 885, '<td valign="top">Interesting concept.  Are the shadows on the statue underexposed, or is it just my monitor?</td>', 'Interesting concept.  Are the shadows on the statue underexposed, or is it just my monitor?', '2002-04-29 15:15:00.000000', NULL, 1),
(55187, 1270, 1042, '<td valign="top">I really liked this shot.</td>', 'I really liked this shot.', '2002-04-29 16:01:00.000000', NULL, 1),
(55188, 1270, 1078, '<td valign="top">Nice composition.  I can''t quite determine if I like the cool tone to it or not -- I think I want the building to be a little warmer, but I don''t think it''s too possible given the site rules.</td>', 'Nice composition.  I can''t quite determine if I like the cool tone to it or not -- I think I want the building to be a little warmer, but I don''t think it''s too possible given the site rules.', '2002-04-29 16:03:00.000000', NULL, 1),
