(55253, 1274, 885, '<td valign="top">Nicely exposed, though I guess some would cry "lens flare!"</td>', 'Nicely exposed, though I guess some would cry "lens flare!"', '2002-04-29 10:43:00.000000', NULL, 1),
(55254, 1274, 1037, '<td valign="top">The layering of the leaves with light behind them is very pretty. I don''t think the picture is framed in an interesting way though. Perhaps the trunk could be more dominant and central? Framing and cropping this photo different ways to experiment could lead to something with more to interest the eye, eg. more bark texture, interesting shapes, etc.</td>', 'The layering of the leaves with light behind them is very pretty. I don''t think the picture is framed in an interesting way though. Perhaps the trunk could be more dominant and central? Framing and cropping this photo different ways to experiment could lead to something with more to interest the eye, eg. more bark texture, interesting shapes, etc.', '2002-04-29 10:59:00.000000', NULL, 1),
(55255, 1274, 681, '<td valign="top">I like the light in this. It has a nice glow to it.</td>', 'I like the light in this. It has a nice glow to it.', '2002-04-29 12:06:00.000000', NULL, 1),
(55256, 1274, 1175, '<td valign="top">I really like this.  I don''t doubt if you get a difference of opinion on my next comment.  I don''t like the glow of the light coming through.</td>', 'I really like this.  I don''t doubt if you get a difference of opinion on my next comment.  I don''t like the glow of the light coming through.', '2002-04-29 12:32:00.000000', NULL, 1),
(55257, 1274, 509, '<td valign="top">I like the effect of the light filtering through the leaves</td>', 'I like the effect of the light filtering through the leaves', '2002-04-29 13:56:00.000000', NULL, 1),
