(55260, 1274, 1242, '<td valign="top">Nice, almost abstract composition.</td>', 'Nice, almost abstract composition.', '2002-04-29 16:49:00.000000', NULL, 1),
(55261, 1274, 1005, '<td valign="top">This really works for me.  You''ve captured the Challenge well and I like the hazy lighting, adds interest to the shot.</td>', 'This really works for me.  You''ve captured the Challenge well and I like the hazy lighting, adds interest to the shot.', '2002-04-29 17:13:00.000000', NULL, 1),
(55262, 1274, 1350, '<td valign="top">I really enjoy the light in this picture...gives it a surreal, dreamlike quality that transcends the usual tree pic. Well done!</td>', 'I really enjoy the light in this picture...gives it a surreal, dreamlike quality that transcends the usual tree pic. Well done!', '2002-04-29 17:17:00.000000', NULL, 1),
(55263, 1274, 675, '<td valign="top">this looks very mystical, i am uncontrolably gravitating towards the alien glow</td>', 'this looks very mystical, i am uncontrolably gravitating towards the alien glow', '2002-04-29 18:27:00.000000', NULL, 1),
(55264, 1274, 1233, '<td valign="top">Surreal.  Neat.</td>', 'Surreal.  Neat.', '2002-04-29 18:51:00.000000', NULL, 1),
(55265, 1274, 843, '<td valign="top">Highlights are way too blown-out.</td>', 'Highlights are way too blown-out.', '2002-04-29 22:42:00.000000', NULL, 1),
(55266, 1274, 459, '<td valign="top">I really like the fuzzy light through the tree.</td>', 'I really like the fuzzy light through the tree.', '2002-04-30 10:29:00.000000', NULL, 1),
(55267, 1274, 1041, '<td valign="top">Photo definitely fulfills the challenge, but not much subject to hold my interest, and the sky is too white and overpowering where it shines through.</td>', 'Photo definitely fulfills the challenge, but not much subject to hold my interest, and the sky is too white and overpowering where it shines through.', '2002-04-30 11:41:00.000000', NULL, 1),
(55268, 1274, 640, '<td valign="top">I really like this tree--very majestic. Nice how the sun is shining through the branches. Maybe because of this the color seems a little off--kind of muted, which distracts from the overall.</td>', 'I really like this tree--very majestic. Nice how the sun is shining through the branches. Maybe because of this the color seems a little off--kind of muted, which distracts from the overall.', '2002-05-01 09:04:00.000000', NULL, 1),
(55269, 1274, 543, '<td valign="top">This really shouldn''t appeal to me - burnt patches of sky, loss in detail on the leaves, blue spill, etc., but it does somehow.  I think it''s the way you caught the light.  I''d crop it from the left to make a vertical composition and avoid some of the distracting elements there.</td>', 'This really shouldn''t appeal to me - burnt patches of sky, loss in detail on the leaves, blue spill, etc., but it does somehow.  I think it''s the way you caught the light.  I''d crop it from the left to make a vertical composition and avoid some of the distracting elements there.', '2002-05-01 10:09:00.000000', NULL, 1),
(55270, 1274, 156, '<td valign="top">for this to represent my interpretation of "from the ground up" there would need to be a lot more tree trunk showing, unless you weren''t standing and zoomed in from the ground instead?</td>', 'for this to represent my interpretation of "from the ground up" there would need to be a lot more tree trunk showing, unless you weren''t standing and zoomed in from the ground instead?', '2002-05-01 13:19:00.000000', NULL, 1),
(55271, 1274, 901, '<td valign="top">the light is dope</td>', 'the light is dope', '2002-05-02 01:59:00.000000', NULL, 1),
(55272, 1274, 715, '<td valign="top">I like the composition of the photo, but the sun shining through the leafs make it difficult to look at.<br/>This probably could have been prevented if the the picture would have been taken on another time of the day or on a less sunnier day.<br/></td>', 'I like the composition of the photo, but the sun shining through the leafs make it difficult to look at.This probably could have been prevented if the the picture would have been taken on another time of the day or on a less sunnier day.', '2002-05-02 12:36:00.000000', NULL, 1),
(55273, 1274, 933, '<td valign="top">Nice effect with the softening of the image.  Good layout too.</td>', 'Nice effect with the softening of the image.  Good layout too.', '2002-05-02 20:47:00.000000', NULL, 1),
(55274, 1274, 1379, '<td valign="top">Awesome textures</td>', 'Awesome textures', '2002-05-03 21:33:00.000000', NULL, 1),
(55275, 1274, 1202, '<td valign="top">Interesting light pattern, good job of exposure with the leaves being back lit.</td>', 'Interesting light pattern, good job of exposure with the leaves being back lit.', '2002-05-04 07:52:00.000000', NULL, 1),
(55276, 1274, 1, '<td valign="top">A slightly amazing glow for a digital camera.  The green still stands out which is nice.</td>', 'A slightly amazing glow for a digital camera.  The green still stands out which is nice.', '2002-05-04 11:16:00.000000', NULL, 1),
