(56103, 1326, 259, '<td valign="top">very nice lighting, and background.</td>', 'very nice lighting, and background.', '2002-04-29 11:47:00.000000', NULL, 1),
(56104, 1326, 544, '<td valign="top">I had a feeling that there would be more pictures in this style, because it has such a fun appeal to it. There weren''t, so that makes your stands out more, especially since it is so well done. The starry night background is fantastic and very fitting. The lighting on the subject is well-done, in that it fits the theme of the picture, but somehow it seems distracting. Maybe it''s because the light is too intense on his right arm where it bleaches out the image. I would have given this picture another point if you had gotten the foot in stronger focus, and dropped the lighting just a notch. Aside from that, great job.</td>', 'I had a feeling that there would be more pictures in this style, because it has such a fun appeal to it. There weren''t, so that makes your stands out more, especially since it is so well done. The starry night background is fantastic and very fitting. The lighting on the subject is well-done, in that it fits the theme of the picture, but somehow it seems distracting. Maybe it''s because the light is too intense on his right arm where it bleaches out the image. I would have given this picture another point if you had gotten the foot in stronger focus, and dropped the lighting just a notch. Aside from that, great job.', '2002-04-29 14:37:00.000000', NULL, 1),
(56105, 1326, 1336, '<td valign="top">beautiful lighting and great use of starry night in the background</td>', 'beautiful lighting and great use of starry night in the background', '2002-04-29 15:01:00.000000', NULL, 1),
(56106, 1326, 1379, '<td valign="top">Ooooh, I love this photo!  So cultured, with the inclusion of Starry Night....  You are an incredibly gifted, visionary photographer!  You should win!</td>', 'Ooooh, I love this photo!  So cultured, with the inclusion of Starry Night....  You are an incredibly gifted, visionary photographer!  You should win!', '2002-04-29 15:07:00.000000', NULL, 1),
(56107, 1326, 813, '<td valign="top">This is hilarious. Extra points too for thematic background. Great concept and execution.</td>', 'This is hilarious. Extra points too for thematic background. Great concept and execution.', '2002-04-29 15:12:00.000000', NULL, 1),
(56108, 1326, 772, '<td valign="top">I like this mannequin shot a little better than the other one in this challenge.  i also liek the van gogh in the background offering some decent contrast.  The lighting coming from the side also enhances the dimension of the mannequin... good job!</td>', 'I like this mannequin shot a little better than the other one in this challenge.  i also liek the van gogh in the background offering some decent contrast.  The lighting coming from the side also enhances the dimension of the mannequin... good job!', '2002-04-29 16:05:00.000000', NULL, 1),
