(56121, 1326, 888, '<td valign="top">fantasticthe monet in the background really sets it apart<br/>(at least I think its a monet!)<br/>Shame you couldn''t have hidden the pole going up his/her ass</td>', 'fantasticthe monet in the background really sets it apart(at least I think its a monet!)Shame you couldn''t have hidden the pole going up his/her ass', '2002-04-30 17:14:00.000000', NULL, 1),
