(56436, 1339, 1, '<td valign="top">Nice idea, the title is excellent.  The sun in the shot is very fitting, but the smudges off the right side are slightly distracting.</td>', 'Nice idea, the title is excellent.  The sun in the shot is very fitting, but the smudges off the right side are slightly distracting.', '2002-04-29 20:12:00.000000', NULL, 1),
(56437, 1339, 843, '<td valign="top">Would be close to perfect if you had cropped that thing out on the right.</td>', 'Would be close to perfect if you had cropped that thing out on the right.', '2002-04-29 22:44:00.000000', NULL, 1),
(56438, 1339, 885, '<td valign="top">The sky is a nice blue (where do you live that you don''t have clouds!?) and the backlighting on the dandelion gives it a nice effect.  I think if you had framed it vertically and shielded the lens to avoid that lens flare, it would have been stronger.</td>', 'The sky is a nice blue (where do you live that you don''t have clouds!?) and the backlighting on the dandelion gives it a nice effect.  I think if you had framed it vertically and shielded the lens to avoid that lens flare, it would have been stronger.', '2002-04-30 09:16:00.000000', NULL, 1),
(56439, 1339, 459, '<td valign="top">cool</td>', 'cool', '2002-04-30 10:08:00.000000', NULL, 1),
(56440, 1339, 472, '<td valign="top">i like the lone solitary soldier quality of this.  even the lens flare and hot spots dont bother me.</td>', 'i like the lone solitary soldier quality of this.  even the lens flare and hot spots dont bother me.', '2002-04-30 11:50:00.000000', NULL, 1),
(56441, 1339, 1041, '<td valign="top">The sun glare and little something on the right are a little distracting.  Nice and crisp dandelion.  I love taking pictures of them, too.</td>', 'The sun glare and little something on the right are a little distracting.  Nice and crisp dandelion.  I love taking pictures of them, too.', '2002-04-30 13:29:00.000000', NULL, 1),
(56442, 1339, 1135, '<td valign="top">Nice, one of my favorites. Might have been better to crop out the tree on the right.</td>', 'Nice, one of my favorites. Might have been better to crop out the tree on the right.', '2002-04-30 17:02:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(56443, 1339, 441, '<td valign="top">great lighting, good shot</td>', 'great lighting, good shot', '2002-04-30 18:12:00.000000', NULL, 1),
(56444, 1339, 543, '<td valign="top">You got the camera down there and pointed up alright.  Good sharpness.  Lens flare detracts, as does the dark whatzit at R.</td>', 'You got the camera down there and pointed up alright.  Good sharpness.  Lens flare detracts, as does the dark whatzit at R.', '2002-05-01 11:17:00.000000', NULL, 1),
(56445, 1339, 1066, '<td valign="top">great macro and I like the little bit of lens flare.  One of my top ten</td>', 'great macro and I like the little bit of lens flare.  One of my top ten', '2002-05-01 17:44:00.000000', NULL, 1),
(56446, 1339, 813, '<td valign="top">Crisp, clear, and delicate. I like.</td>', 'Crisp, clear, and delicate. I like.', '2002-05-01 17:47:00.000000', NULL, 1),
(56447, 1339, 244, '<td valign="top">I like this shot, think it would have been nice to have a few of them blowing off while you took it.<br/></td>', 'I like this shot, think it would have been nice to have a few of them blowing off while you took it.', '2002-05-01 19:03:00.000000', NULL, 1),
(56448, 1339, 446, '<td valign="top">Tough exposure to control.  The lens flare is distracting.  Maybe a lens hood or shielding of the sun from the lens with your hand with or without a hood may have helped?  Shooting at a different time of day (I would guess this photo was shot at mid day), or at an angle away from the sun may have given you more control of the light also.  Your primary subject has excessive blown highlights.  I still like the idea for it''s simplicity.</td>', 'Tough exposure to control.  The lens flare is distracting.  Maybe a lens hood or shielding of the sun from the lens with your hand with or without a hood may have helped?  Shooting at a different time of day (I would guess this photo was shot at mid day), or at an angle away from the sun may have given you more control of the light also.  Your primary subject has excessive blown highlights.  I still like the idea for it''s simplicity.', '2002-05-01 21:34:00.000000', NULL, 1),
(56449, 1339, 933, '<td valign="top">Nice photo.  The lighting is a bit distracting.  But all in all, very nice.</td>', 'Nice photo.  The lighting is a bit distracting.  But all in all, very nice.', '2002-05-02 14:58:00.000000', NULL, 1),
(56450, 1339, 301, '<td valign="top">very nice. I like the lens flare.  Crop the shadow on the right hand side though</td>', 'very nice. I like the lens flare.  Crop the shadow on the right hand side though', '2002-05-03 11:47:00.000000', NULL, 1),
(56451, 1339, 739, '<td valign="top">Did you try taking a shot with the seeds in the air? I had the same idea for such a shot, but never got around to it.</td>', 'Did you try taking a shot with the seeds in the air? I had the same idea for such a shot, but never got around to it.', '2002-05-03 12:08:00.000000', NULL, 1),
(56452, 1339, 828, '<td valign="top">Really feels like midsummer.  I like it.</td>', 'Really feels like midsummer.  I like it.', '2002-05-03 23:27:00.000000', NULL, 1),
(56453, 1339, 1202, '<td valign="top">This is a time when the blowout exemplifies the light source, which I feel is an integral part of this shot.   I like it for a difficult challenge.</td>', 'This is a time when the blowout exemplifies the light source, which I feel is an integral part of this shot.   I like it for a difficult challenge.', '2002-05-04 08:16:00.000000', NULL, 1),
(56454, 1339, 749, '<td valign="top">Very impressive - was the shot taken from on the ground, or did you pick the flower first and hold it up? :o)</td>', 'Very impressive - was the shot taken from on the ground, or did you pick the flower first and hold it up? :o)', '2002-05-05 09:49:00.000000', NULL, 1),
(56455, 1340, 352, '<td valign="top">Excellent!  Good DOF, very nice contrast, good focus.</td>', 'Excellent!  Good DOF, very nice contrast, good focus.', '2002-04-29 01:58:00.000000', NULL, 1),
(56456, 1340, 801, '<td valign="top">great shot!! congratulations</td>', 'great shot!! congratulations', '2002-04-29 04:02:00.000000', NULL, 1),
(56457, 1340, 1209, '<td valign="top">Cute image. Would like to have seen some space between dog and branch, though.</td>', 'Cute image. Would like to have seen some space between dog and branch, though.', '2002-04-29 09:39:00.000000', NULL, 1),
(56458, 1340, 1024, '<td valign="top">Cute picture.</td>', 'Cute picture.', '2002-04-29 09:46:00.000000', NULL, 1),
(56459, 1340, 656, '<td valign="top">cool pose</td>', 'cool pose', '2002-04-29 10:03:00.000000', NULL, 1),
(56460, 1340, 259, '<td valign="top">one of the better pics so far that i have seen.</td>', 'one of the better pics so far that i have seen.', '2002-04-29 11:01:00.000000', NULL, 1),
(56461, 1340, 772, '<td valign="top">Stella looks like a nice dog :)  Good challenge interpretation...</td>', 'Stella looks like a nice dog :)  Good challenge interpretation...', '2002-04-29 14:35:00.000000', NULL, 1),
(56462, 1340, 1336, '<td valign="top">great use of a clear blue sky.  i like the contrast</td>', 'great use of a clear blue sky.  i like the contrast', '2002-04-29 14:58:00.000000', NULL, 1),
(56463, 1340, 1379, '<td valign="top">Awww, Stella is so cute!  Nice catchlights on her little nose!</td>', 'Awww, Stella is so cute!  Nice catchlights on her little nose!', '2002-04-29 15:05:00.000000', NULL, 1),
(56464, 1340, 962, '<td valign="top">Great colors....</td>', 'Great colors....', '2002-04-29 16:36:00.000000', NULL, 1),
(56465, 1340, 327, '<td valign="top">Nice execution.</td>', 'Nice execution.', '2002-04-29 16:49:00.000000', NULL, 1),
(56466, 1340, 675, '<td valign="top">this is definitely one of the best shots in this contest, that dog looks so stoic</td>', 'this is definitely one of the best shots in this contest, that dog looks so stoic', '2002-04-29 18:21:00.000000', NULL, 1),
(56467, 1340, 724, '<td valign="top">Beautiful color, great sky, sweet dog!! Great job!  What is that white dot in the lower left hand corner?</td>', 'Beautiful color, great sky, sweet dog!! Great job!  What is that white dot in the lower left hand corner?', '2002-04-29 22:39:00.000000', NULL, 1),
(56468, 1340, 1323, '<td valign="top">Great title, must be into jazz.</td>', 'Great title, must be into jazz.', '2002-04-29 23:09:00.000000', NULL, 1),
(56469, 1340, 142, '<td valign="top">Stella is cute!  You have her framed perfectly and the tree adds a nice touch.</td>', 'Stella is cute!  You have her framed perfectly and the tree adds a nice touch.', '2002-04-30 06:10:00.000000', NULL, 1),
(56470, 1340, 1041, '<td valign="top">She''s a cutie!  And well in focus, too.  Good perspective on her.  Don''t like the branch above her, though.</td>', 'She''s a cutie!  And well in focus, too.  Good perspective on her.  Don''t like the branch above her, though.', '2002-04-30 13:09:00.000000', NULL, 1),
(56471, 1340, 888, '<td valign="top">A good old highland terrier (I think)<br/>Very good shot<br/>I think I spy the moon in the pictuer too!</td>', 'A good old highland terrier (I think)Very good shotI think I spy the moon in the pictuer too!', '2002-04-30 14:23:00.000000', NULL, 1),
(56472, 1340, 554, '<td valign="top">What a sweet doggy. Don''t feed her canned food. Feed Eukanuba dry.<br/>top 3</td>', 'What a sweet doggy. Don''t feed her canned food. Feed Eukanuba dry.top 3', '2002-04-30 14:23:00.000000', NULL, 1),
(56473, 1340, 1135, '<td valign="top">Beautiful Sky! Nice.</td>', 'Beautiful Sky! Nice.', '2002-04-30 16:58:00.000000', NULL, 1),
(56474, 1340, 640, '<td valign="top">This is wonderful! How''d you get your dog to look up like that? Great idea!</td>', 'This is wonderful! How''d you get your dog to look up like that? Great idea!', '2002-05-01 09:09:00.000000', NULL, 1),
(56475, 1340, 885, '<td valign="top">Cute doggie.  Nice colors and natural light.  I think maybe if the dog had been less centered...maybe if the tree were not ''attached'' to her head, but if there were some space between them...</td>', 'Cute doggie.  Nice colors and natural light.  I think maybe if the dog had been less centered...maybe if the tree were not ''attached'' to her head, but if there were some space between them...', '2002-05-01 09:46:00.000000', NULL, 1),
(56476, 1340, 543, '<td valign="top">Is that the moon?  Nice.  Better, perhaps, with the tree coming from behind the dog''s head (sort of going the same direction as her gaze) if possible.  Good, sharp fur, and even a catchlight in her eye.</td>', 'Is that the moon?  Nice.  Better, perhaps, with the tree coming from behind the dog''s head (sort of going the same direction as her gaze) if possible.  Good, sharp fur, and even a catchlight in her eye.', '2002-05-01 10:41:00.000000', NULL, 1),
(56477, 1340, 156, '<td valign="top">hey, is that the moon too?</td>', 'hey, is that the moon too?', '2002-05-01 13:20:00.000000', NULL, 1),
(56478, 1340, 933, '<td valign="top">Nice pose &amp; color.  Good clarity on the dog.  I think I might have liked it a bit better if the tree were in the upper left. But still, a great shot and rated high.</td>', 'Nice pose & color.  Good clarity on the dog.  I think I might have liked it a bit better if the tree were in the upper left. But still, a great shot and rated high.', '2002-05-01 13:58:00.000000', NULL, 1),
(56479, 1340, 446, '<td valign="top">Great subject and framing of the dog.  The colors look unnatural, especially the sky.  Post processed for color, sharpness, and saturation?  If so, you might consider backing off a little.  Good effort.</td>', 'Great subject and framing of the dog.  The colors look unnatural, especially the sky.  Post processed for color, sharpness, and saturation?  If so, you might consider backing off a little.  Good effort.', '2002-05-01 21:26:00.000000', NULL, 1),
(56480, 1340, 748, '<td valign="top">Simple, but effective.</td>', 'Simple, but effective.', '2002-05-02 19:03:00.000000', NULL, 1),
(56481, 1340, 1290, '<td valign="top">What an aristocratic face - great photo.<br/></td>', 'What an aristocratic face - great photo.', '2002-05-02 19:48:00.000000', NULL, 1),
(56482, 1340, 330, '<td valign="top">Good picture. I see you went for the "cute" vote.</td>', 'Good picture. I see you went for the "cute" vote.', '2002-05-03 07:11:00.000000', NULL, 1),
(56483, 1340, 1202, '<td valign="top">This one pulls on the heart strings.   Oh, what a breath of fresh air can do!   The tree doesn''t help.</td>', 'This one pulls on the heart strings.   Oh, what a breath of fresh air can do!   The tree doesn''t help.', '2002-05-04 09:40:00.000000', NULL, 1),
(56484, 1340, 1457, '<td valign="top">benji, you can fly!</td>', 'benji, you can fly!', '2002-05-04 23:01:00.000000', NULL, 1),
(56485, 1340, 1, '<td valign="top">The branches are distracting from your subject</td>', 'The branches are distracting from your subject', '2002-05-05 23:09:00.000000', NULL, 1),
(56486, 1340, 2, '<td valign="top">Nice, bold colors on this shot.  Cool picture.</td>', 'Nice, bold colors on this shot.  Cool picture.', '2002-05-06 00:59:00.000000', NULL, 1),
(56487, 1340, 459, '<td valign="top">Thanks for all the comments.  The photo was only adjusted by sharpening a little bit.  No color adjustments.  It was a beautiful day.</td>', 'Thanks for all the comments.  The photo was only adjusted by sharpening a little bit.  No color adjustments.  It was a beautiful day.', '2002-05-06 08:12:00.000000', NULL, 0),
(56488, 1341, 352, '<td valign="top">Love the perspective.  I might have made the escalators a bit more symmetrical in the framing.</td>', 'Love the perspective.  I might have made the escalators a bit more symmetrical in the framing.', '2002-04-29 01:52:00.000000', NULL, 1),
(56489, 1341, 1024, '<td valign="top">Good use of black and white.</td>', 'Good use of black and white.', '2002-04-29 09:25:00.000000', NULL, 1),
(56490, 1341, 656, '<td valign="top">good use of B&amp;W, shame you lost the edges of the bottom railings.  seems slightly tilted too which would annoy after a while.  Like the hidden shadowy figure on the left.</td>', 'good use of B&W, shame you lost the edges of the bottom railings.  seems slightly tilted too which would annoy after a while.  Like the hidden shadowy figure on the left.', '2002-04-29 09:29:00.000000', NULL, 1),
(56491, 1341, 885, '<td valign="top">Cool how the escalators blurred in the long exposure.  I don''t know what the light and dark triangles up the stairs are, but I like them.  Would it have been possible to catch the top of the arch of the tunnel?  Well done.</td>', 'Cool how the escalators blurred in the long exposure.  I don''t know what the light and dark triangles up the stairs are, but I like them.  Would it have been possible to catch the top of the arch of the tunnel?  Well done.', '2002-04-29 10:46:00.000000', NULL, 1),
(56492, 1341, 189, '<td valign="top">LOVE the elevation.</td>', 'LOVE the elevation.', '2002-04-29 11:07:00.000000', NULL, 1),
(56493, 1341, 1037, '<td valign="top">Very interesting, in a kind of art deco way :).  The amount of contrast is very pleasing. The only thing that distracts me is that the vanishing point is slightly off-centre. The interplay of light and shadow on those steps is engaging.</td>', 'Very interesting, in a kind of art deco way :).  The amount of contrast is very pleasing. The only thing that distracts me is that the vanishing point is slightly off-centre. The interplay of light and shadow on those steps is engaging.', '2002-04-29 11:32:00.000000', NULL, 1),
(56494, 1341, 259, '<td valign="top">nice lighting</td>', 'nice lighting', '2002-04-29 11:56:00.000000', NULL, 1),
(56495, 1341, 714, '<td valign="top">Very nice.</td>', 'Very nice.', '2002-04-29 12:19:00.000000', NULL, 1),
(56496, 1341, 509, '<td valign="top">Feels slightly tilted to the right, otherwise well done</td>', 'Feels slightly tilted to the right, otherwise well done', '2002-04-29 14:01:00.000000', NULL, 1),
(56497, 1341, 1336, '<td valign="top">nice use of black and white.</td>', 'nice use of black and white.', '2002-04-29 14:58:00.000000', NULL, 1),
(56498, 1341, 675, '<td valign="top">another interesting shot, it reminds me of prague. b &amp; w adds to the mystique - achiral</td>', 'another interesting shot, it reminds me of prague. b & w adds to the mystique - achiral', '2002-04-29 18:54:00.000000', NULL, 1),
(56499, 1341, 843, '<td valign="top">Awesome shot. Like the B&amp;W. I also like the funky patterns in the stairs. Would give it a 10 if it were centered better. Still a good score though, nice job.</td>', 'Awesome shot. Like the B&W. I also like the funky patterns in the stairs. Would give it a 10 if it were centered better. Still a good score though, nice job.', '2002-04-29 22:13:00.000000', NULL, 1),
(56500, 1341, 1209, '<td valign="top">Interesting study of light and shadows. Well  composed.</td>', 'Interesting study of light and shadows. Well  composed.', '2002-04-30 01:22:00.000000', NULL, 1),
(56501, 1341, 587, '<td valign="top">fantastic shot.</td>', 'fantastic shot.', '2002-04-30 07:39:00.000000', NULL, 1),
(56502, 1341, 772, '<td valign="top">I like this shot!  I especially like the longer exposure that blurred out the escalator steps... nice work!</td>', 'I like this shot!  I especially like the longer exposure that blurred out the escalator steps... nice work!', '2002-04-30 10:49:00.000000', NULL, 1),
(56503, 1341, 1041, '<td valign="top">Did you take this in the middle of the night or cordon it off so that there''s no people on it?  ;o)  Nice shot.</td>', 'Did you take this in the middle of the night or cordon it off so that there''s no people on it?  ;o)  Nice shot.', '2002-04-30 13:36:00.000000', NULL, 1),
(56504, 1341, 888, '<td valign="top">realy nice.<br/>What are te strange shapes on te stairs? Light reflection or worn stairs?</td>', 'realy nice.What are te strange shapes on te stairs? Light reflection or worn stairs?', '2002-04-30 14:03:00.000000', NULL, 1),
(56505, 1341, 543, '<td valign="top">You''re now allowed to rotate to straighten, and probably should here.  Nice leading composistion, and I especially like the triangles on the stairs.  Gotta vote to disqualify, though, as this is taken from *below* the ground up.  {jk}</td>', 'You''re now allowed to rotate to straighten, and probably should here.  Nice leading composistion, and I especially like the triangles on the stairs.  Gotta vote to disqualify, though, as this is taken from *below* the ground up.  {jk}', '2002-05-01 10:39:00.000000', NULL, 1),
(56506, 1341, 156, '<td valign="top">EXcellent composition and lighting....could be just me but it seems as if the camera is at handrail height looking up versus at ground level looking up...</td>', 'EXcellent composition and lighting....could be just me but it seems as if the camera is at handrail height looking up versus at ground level looking up...', '2002-05-01 13:28:00.000000', NULL, 1),
(56507, 1341, 739, '<td valign="top">There is a weird effect going on.  My brain wants to interpret this as a long set of stairs, but the lights on the wall (horizontal and converging) makes this look flat.  Has a tunneling effect...interesting.</td>', 'There is a weird effect going on.  My brain wants to interpret this as a long set of stairs, but the lights on the wall (horizontal and converging) makes this look flat.  Has a tunneling effect...interesting.', '2002-05-01 21:12:00.000000', NULL, 1),
(56508, 1341, 301, '<td valign="top">nice composition</td>', 'nice composition', '2002-05-02 05:19:00.000000', NULL, 1),
(56509, 1341, 933, '<td valign="top">Nie composition.  Good use of B&amp;W.</td>', 'Nie composition.  Good use of B&W.', '2002-05-02 15:03:00.000000', NULL, 1),
(56510, 1341, 640, '<td valign="top">B&amp;W works great here. It gives me the feeling of depth rather than height.</td>', 'B&W works great here. It gives me the feeling of depth rather than height.', '2002-05-03 01:24:00.000000', NULL, 1),
(56511, 1341, 446, '<td valign="top">You definitely got the sense of looking up.  Very dramatacic shot.  However, as a black and white photo it seems the gradations are too severe and the number of blown highlights keeps it from scoring very high.  You are on to some good ideas here.  Good job.</td>', 'You definitely got the sense of looking up.  Very dramatacic shot.  However, as a black and white photo it seems the gradations are too severe and the number of blown highlights keeps it from scoring very high.  You are on to some good ideas here.  Good job.', '2002-05-03 21:31:00.000000', NULL, 1),
(56512, 1341, 1202, '<td valign="top">I am led to the top with this one and it makes me tiered just looking at the climb.   NIce B/W with much of the gray scale represented.</td>', 'I am led to the top with this one and it makes me tiered just looking at the climb.   NIce B/W with much of the gray scale represented.', '2002-05-04 08:28:00.000000', NULL, 1),
(56513, 1341, 1457, '<td valign="top">i''ve never been on a subway, but I hear I''m not missing out</td>', 'i''ve never been on a subway, but I hear I''m not missing out', '2002-05-04 23:03:00.000000', NULL, 1),
(56514, 1341, 1, '<td valign="top">Cool shot, the b/w fits it well.  Perfect framing.</td>', 'Cool shot, the b/w fits it well.  Perfect framing.', '2002-05-05 23:08:00.000000', NULL, 1),
(56527, 1346, 205, '<td valign="top">this is very interesting</td>', 'this is very interesting', '2002-04-29 01:27:00.000000', NULL, 1),
(56528, 1346, 1024, '<td valign="top">This would have been a bit nicer if the sky was not overcast.  Some additional color would have worked  better.</td>', 'This would have been a bit nicer if the sky was not overcast.  Some additional color would have worked  better.', '2002-04-29 09:22:00.000000', NULL, 1),
(56529, 1346, 656, '<td valign="top">Like the grass used for framing.  What is this ?</td>', 'Like the grass used for framing.  What is this ?', '2002-04-29 09:30:00.000000', NULL, 1),
(56530, 1346, 675, '<td valign="top">weird, nice shot, but the way the shot was taken at a slight angle takes away from the power of the shot</td>', 'weird, nice shot, but the way the shot was taken at a slight angle takes away from the power of the shot', '2002-04-29 09:44:00.000000', NULL, 1),
(56531, 1346, 509, '<td valign="top">I like everything about this except the sky, I think an overcast darker sky would create a mood more befitting this shot.  Nicely done</td>', 'I like everything about this except the sky, I think an overcast darker sky would create a mood more befitting this shot.  Nicely done', '2002-04-29 13:58:00.000000', NULL, 1),
(56532, 1346, 1336, '<td valign="top">this is a neat photo.  great contrast.</td>', 'this is a neat photo.  great contrast.', '2002-04-29 14:55:00.000000', NULL, 1),
(56533, 1346, 1379, '<td valign="top">Right on!  Love the intense grassiness in the foreground.  I''m *there*.</td>', 'Right on!  Love the intense grassiness in the foreground.  I''m *there*.', '2002-04-29 15:16:00.000000', NULL, 1),
(56534, 1346, 1323, '<td valign="top">The grass in the foreground is nice.</td>', 'The grass in the foreground is nice.', '2002-04-29 18:42:00.000000', NULL, 1),
(56535, 1346, 661, '<td valign="top">Too bad no blue sky. Interesting picture.</td>', 'Too bad no blue sky. Interesting picture.', '2002-04-29 18:45:00.000000', NULL, 1),
(56536, 1346, 885, '<td valign="top">Good exposure on the cross.  Sky is a bit white, but that was probably unavoidable.  How big is this?  It''s hard to tell a sense of scale..I''m wondering if something else in the foreground other than the grass, or maybe a less straight-ahead angle would make this picture more interesting.</td>', 'Good exposure on the cross.  Sky is a bit white, but that was probably unavoidable.  How big is this?  It''s hard to tell a sense of scale..I''m wondering if something else in the foreground other than the grass, or maybe a less straight-ahead angle would make this picture more interesting.', '2002-04-30 08:07:00.000000', NULL, 1),
(56537, 1346, 714, '<td valign="top">cool,  Nice colors and lighting.</td>', 'cool,  Nice colors and lighting.', '2002-04-30 09:43:00.000000', NULL, 1),
(56538, 1346, 772, '<td valign="top">Beautiful photo!  I like!  I hope to hear more about what and where this is after the challenge is over :)</td>', 'Beautiful photo!  I like!  I hope to hear more about what and where this is after the challenge is over :)', '2002-04-30 10:51:00.000000', NULL, 1),
(56539, 1346, 1041, '<td valign="top">I like the blurry grass in the foreground and then everything else behind it being in focus.  The sculpture is a little centered for my taste.</td>', 'I like the blurry grass in the foreground and then everything else behind it being in focus.  The sculpture is a little centered for my taste.', '2002-04-30 13:08:00.000000', NULL, 1),
